<?php
/**
 * SEAL_Sidebar — builds the ILL navigation sidebar.
 *
 * Reproduces the left-hand nav column the original standalone site had hard-typed
 * into the WordPress page body. Now generated by the plugin so it travels with
 * any deployment and adapts to the logged-in user's capabilities.
 *
 * Sections (shown only if the user has the capability for at least one link):
 *   - Edit Profiles
 *   - Request Status
 *   - Statistics
 *   - System Staff   (libsys-tier capabilities)
 *   - ILL Admin       (administrator-tier capabilities)
 *   - Quick Links    (configurable via admin → Branding / Quick Links)
 *
 * @author Zachary Spalding (SENYLRC) & Claude (Anthropic)
 */

if ( ! defined( 'ABSPATH' ) ) { exit; }

class SEAL_Sidebar {

    /**
     * Render the sidebar nav as HTML.
     * Each link is gated by the same capability its route requires, so users
     * only see what they can actually open.
     */
    public static function render(): string {
        if ( ! is_user_logged_in() ) {
            return '';
        }

        $sys = seal_config( 'system_name' );

        // Section => [ [ label, path, capability ], ... ]
        $sections = [
            'Edit Profiles' => [
                [ 'User Profile',            '/illuser',          'seal_view_own' ],
                [ 'Library Profile',         '/libprofile',       'seal_request'  ],
                [ 'View Library Accounts',   '/libstaffaccounts', 'seal_view_own' ],
            ],
            'Request Status' => [
                [ 'Borrowing Requests',      '/requesthistory',   'seal_view_own' ],
                [ 'Lending Requests',        '/lender-history',   'seal_view_own' ],
            ],
            'Statistics' => [
                [ 'Borrowing Statistics',    '/libstats',         'seal_view_own' ],
                [ 'Lending Statistics',      '/liblenderstat',    'seal_view_own' ],
            ],
            'System Staff' => [
                [ 'Manage Accounts',         '/adminlib-accounts-ls','seal_view_system' ],
                [ 'Manage All Requests',     '/allrequests-ls',   'seal_view_system' ],
                [ 'Manage Library',          '/adminlib-ls',      'seal_adminlib_ls' ],
                [ 'System Statistics',       '/stats-ls',         'seal_stats_system' ],
            ],
            'ILL Admin' => [
                [ 'Manage All Libraries',    '/adminlib',         'seal_admin' ],
                [ 'User Accounts',           '/adminlib-accounts','seal_admin' ],
                [ 'All Requests',            '/allrequests',      'seal_admin' ],
                [ ( seal_config( 'org_name' ) ?: 'System' ) . ' Stats', '/stats', 'seal_sealstats' ],
                [ 'Overall System Stats',    '/systemstats',      'seal_systemstats' ],
                [ 'ILLiad Mapping',          '/illiad-mapping',   'seal_admin' ],
                [ 'Resend a Request',        '/resend',           'seal_admin' ],
                [ 'Automatic Fallback (Rota)', '/rota',           'seal_admin' ],
                [ 'Email Harvest',           '/email-harvest',    'seal_email_harvest' ],
            ],
        ];

        // The "ILL Admin" heading uses the system name where it makes sense,
        // but the user asked specifically for "ILL Admin" (not "SENYLRC Admin").
        $current_path = self::current_path();

        ob_start();
        ?>
        <nav class="seal-sidebar-nav" aria-label="<?php echo esc_attr( $sys ); ?> navigation">
            <ul class="seal-sidebar-top">
                <li><a href="<?php echo esc_url( home_url( '/' ) ); ?>">Home</a></li>
                <li><a href="<?php echo esc_url( wp_logout_url( home_url() ) ); ?>">Logout</a></li>
            </ul>
            <?php
            foreach ( $sections as $heading => $links ) {
                // Filter to links the user can access
                $visible = array_filter( $links, static function ( $link ) {
                    return current_user_can( $link[2] );
                } );

                if ( empty( $visible ) ) {
                    continue; // skip whole section if no accessible links
                }
                ?>
                <h6><?php echo esc_html( $heading ); ?></h6>
                <?php
                foreach ( $visible as $link ) {
                    [ $label, $path, $cap ] = $link;
                    $url      = home_url( $path );
                    $is_here  = ( untrailingslashit( $current_path ) === untrailingslashit( $path ) );
                    $aria     = $is_here ? ' aria-current="page"' : '';
                    $cls      = $is_here ? ' class="seal-current"' : '';
                    echo '<a href="' . esc_url( $url ) . '"' . $cls . $aria . '>'
                        . esc_html( $label ) . '</a><br>';
                }
            }

            // ── Quick Links (configurable) ────────────────────────────────
            $quick = self::quick_links();
            if ( ! empty( $quick ) ) {
                echo '<h6>Quick Links</h6><p>';
                foreach ( $quick as $ql ) {
                    $target = $ql['external'] ? ' target="_blank" rel="noopener noreferrer"' : '';
                    echo '<a href="' . esc_url( $ql['url'] ) . '"' . $target . '>'
                        . esc_html( $ql['label'] ) . ( $ql['external'] ? '<span class="seal-sr-only"> (opens in a new tab)</span>' : '' ) . '</a><br>';
                }
                echo '</p>';
            }
            ?>
        </nav>
        <?php
        return ob_get_clean();
    }

    /**
     * Parse the configurable quick-links option.
     * Stored as newline-separated  Label|URL  pairs in seal_config('quick_links').
     * A URL pointing off-site opens in a new tab.
     */
    private static function quick_links(): array {
        $raw = seal_config( 'quick_links' );
        $out = [];

        if ( $raw ) {
            $home_host = wp_parse_url( home_url(), PHP_URL_HOST );
            foreach ( array_filter( array_map( 'trim', explode( "\n", $raw ) ) ) as $line ) {
                $parts = explode( '|', $line, 2 );
                if ( count( $parts ) < 2 ) { continue; }
                $label = trim( $parts[0] );
                $url   = trim( $parts[1] );
                if ( $label === '' || $url === '' ) { continue; }
                $host  = wp_parse_url( $url, PHP_URL_HOST );
                $out[] = [
                    'label'    => $label,
                    'url'      => $url,
                    'external' => ( $host && $host !== $home_host ),
                ];
            }
        }

        return $out;
    }

    /** Current request path (no host, no query). */
    private static function current_path(): string {
        $uri = isset( $_SERVER['REQUEST_URI'] )
            ? sanitize_url( wp_unslash( $_SERVER['REQUEST_URI'] ) )
            : '';
        $path = wp_parse_url( $uri, PHP_URL_PATH ) ?: '';
        return '/' . trim( $path, '/' );
    }
}
